'use strict';
let intentFilters=[],excludedIngredients=[],intentWarnings=[],pickedIngredients=new Set(),parsedIngredients=[],ingredientTab='常用',ingredientBusy=false,lastIntentText='';
const originalParams=params;
params=function(){const p=originalParams();p.set('filters',JSON.stringify(intentFilters));p.set('exclude_components',excludedIngredients.join(','));if(p.get('kind')&&intentFilters.some(f=>f.kind===p.get('kind')&&(f.unit||'')===(p.get('unit')||''))){p.delete('kind');p.delete('unit');p.delete('lo');p.delete('hi')}return p};
window.revealResults=()=>document.body.classList.remove('search-home');
const ingredientNames={'SiO2':'二氧化硅','B2O3':'氧化硼','Al2O3':'氧化铝','MgO':'氧化镁','CaO':'氧化钙','Na2O':'氧化钠','K2O':'氧化钾','Li2O':'氧化锂','P2O5':'五氧化二磷','GeO2':'二氧化锗','BaO':'氧化钡','SrO':'氧化锶','ZnO':'氧化锌','TiO2':'二氧化钛','ZrO2':'二氧化锆','Fe2O3':'氧化铁','FeO':'氧化亚铁','La2O3':'氧化镧','Y2O3':'氧化钇','PbO':'氧化铅','Bi2O3':'氧化铋','CeO2':'二氧化铈','Nb2O5':'五氧化二铌','Ta2O5':'五氧化二钽','WO3':'三氧化钨','TeO2':'二氧化碲','Sb2O3':'三氧化二锑','SnO2':'二氧化锡','CaF2':'氟化钙','BaF2':'氟化钡','NaF':'氟化钠','LiF':'氟化锂','AlF3':'氟化铝','ZrF4':'四氟化锆'};
const commonGroups=[['网络形成氧化物',['SiO2','B2O3','P2O5','GeO2','TeO2']],['碱金属氧化物',['Li2O','Na2O','K2O','Rb2O','Cs2O']],['碱土金属氧化物',['BeO','MgO','CaO','SrO','BaO']],['其他常用氧化物',['Al2O3','ZnO','TiO2','ZrO2','Fe2O3','FeO','PbO','Bi2O3','Sb2O3','SnO2','Nb2O5','Ta2O5','WO3','MoO3']],['稀土氧化物',['La2O3','Y2O3','CeO2','Nd2O3','Er2O3','Gd2O3']],['常用卤化物',['LiF','NaF','KF','MgF2','CaF2','SrF2','BaF2','AlF3','ZrF4','LaF3','NaCl','KCl']],['硫族玻璃组分',['As2S3','GeS2','Sb2S3','As2Se3','GeSe2','GeTe','Se','Te','S']]];
function classifyIngredient(co){if(/^[A-Z][a-z]?$/.test(co))return '元素';if(/(?:F|Cl|Br|I)\d*/.test(co))return '卤化物';if(/(?:Se|Te|S)\d*/.test(co)&&!co.includes('O'))return '硫/硒/碲化物';if(co.includes('O')&&!/[()]/.test(co))return '氧化物';return '其他组分'}
function renderIngredients(){if(!summary)return;const needle=$('ingredientQuery').value.trim().toLowerCase().replace(/[₀-₉]/g,c=>'₀₁₂₃₄₅₆₇₈₉'.indexOf(c)),all=summary.components.filter(x=>!needle||x.name.toLowerCase().includes(needle)||(ingredientNames[x.name]||'').includes(needle));const pool=new Map(all.map(x=>[x.name,x]));let groups;
if(ingredientTab==='常用'&&!needle)groups=commonGroups.map(([title,keys])=>[title,keys.map(k=>pool.get(k)).filter(Boolean)]);
else{const vals=all.filter(x=>ingredientTab==='全部'||ingredientTab==='常用'||classifyIngredient(x.name)===ingredientTab).sort((a,b)=>b.n-a.n||a.name.localeCompare(b.name));groups=[[needle?'原料搜索结果':ingredientTab,vals]]}
$('ingredientGrid').innerHTML=groups.filter(([title,items])=>items.length).map(([title,items])=>`<section class="ingredient-section"><h3>${esc(title)} <small>${items.length} 种</small></h3><div class="ingredient-tiles">${items.map(x=>`<button class="ingredient-tile ${classifyIngredient(x.name)==='元素'?'atomic':'compound'} ${components.includes(x.name)?'selected':''}" data-ingredient="${esc(x.name)}" aria-pressed="${components.includes(x.name)}" aria-label="${esc(x.name)} ${esc(ingredientNames[x.name]||'')} ${fmt(x.n)}条材料"><small>${fmt(x.n)} 条</small><strong>${chem(x.name)}</strong><span>${esc(ingredientNames[x.name]||classifyIngredient(x.name))}</span><i aria-hidden="true">${components.includes(x.name)?'✓':'+'}</i></button>`).join('')}</div></section>`).join('')||'<div class="no-results">没有匹配的原料，请检查化学式或切换“全部”。</div>';
$('ingredientSelected').innerHTML=components.map(k=>`<button data-ingredient="${esc(k)}">${chem(k)} ×</button>`).join('');$('ingredientStatus').textContent=`已选 ${components.length} 种组分`;$('ingredientCount').textContent=components.length?`已选 ${components.length} 种`:'多选组分';$('ingredientTabs').innerHTML=['常用','氧化物','卤化物','硫/硒/碲化物','元素','其他组分','全部'].map(t=>`<button class="${t===ingredientTab?'active':''}" data-ingredient-tab="${t}" aria-pressed="${t===ingredientTab}">${t}</button>`).join('')}
function filterText(f){const range=f.lo!=null&&f.hi!=null&&f.lo===f.hi?'= '+fmt(f.lo):[f.lo!=null?(f.lo_inclusive===false?'> ':'≥ ')+fmt(f.lo):'',f.hi!=null?(f.hi_inclusive===false?'< ':'≤ ')+fmt(f.hi):''].filter(Boolean).join(' 且 ');return `${f.kind} ${range} ${f.unit==='1'?'':unitText(f.unit)}${f.freq!=null?' · '+fmt(f.freq/1e6)+' MHz':''}${f.temp!=null?' · '+fmt(f.temp)+' °C':''}`}
function selectKindOption(kind,unit){const sel=$('kind');for(const opt of sel.options){if(!opt.value)continue;try{const[k,u]=JSON.parse(opt.value);if(k===kind&&u===unit){sel.value=opt.value;if(sel.onchange)sel.onchange();return true}}catch{}}return false}
function fillAdvancedFromFilter(f){if(!f){if($('kind'))$('kind').value='';if($('lo'))$('lo').value='';if($('hi'))$('hi').value='';if($('kind')&&$('kind').onchange)$('kind').onchange();return}if(selectKindOption(f.kind,f.unit)){$('lo').value=f.lo??'';$('hi').value=f.hi??'';if($('kind').onchange)$('kind').onchange()}}
function upsertAdvancedIntoIntent(){if(!$('kind').value)return;const[kind,unit]=JSON.parse($('kind').value);const lo=$('lo').value===''?null:Number($('lo').value);const hi=$('hi').value===''?null:Number($('hi').value);if(lo==null&&hi==null)return;const f={kind,unit,lo,hi,lo_inclusive:true,hi_inclusive:true};const i=intentFilters.findIndex(x=>x.kind===kind&&x.unit===unit);if(i>=0)intentFilters[i]=Object.assign({},intentFilters[i],f);else intentFilters.push(f)}
function hasRecognizedIntent(d){return (d.components&&d.components.length)||(d.exclude_components&&d.exclude_components.length)||(d.filters&&d.filters.length)||(d.q&&d.q.trim())||d.source||d.pcb}
function renderIntent(){const chipHtml=[];if(components.length||intentFilters.length||excludedIngredients.length||$('query').value.trim()||$('source').value||$('pcb').checked)chipHtml.push('<span class="chips-label">已解读条件</span>');chipHtml.push(...components.map(k=>`<button type="button" data-remove-component="${esc(k)}" class="component-token">${chem(k)} ×</button>`));chipHtml.push(...intentFilters.map((f,i)=>`<span class="property-token"><button type="button" data-edit-filter="${i}" title="在高级筛选中修改">${esc(filterText(f))}</button><button type="button" data-remove-filter="${i}" aria-label="取消该性质条件">×</button></span>`));chipHtml.push(...excludedIngredients.map(k=>`<button type="button" data-remove-exclude="${esc(k)}" class="exclude-token">不含 ${chem(k)} ×</button>`));if($('query').value.trim())chipHtml.push(`<button type="button" data-remove-query="1" class="keyword-token">关键词 ${esc($('query').value.trim())} ×</button>`);if($('source').value)chipHtml.push(`<button type="button" data-remove-source="1" class="source-token">来源 ${esc(sourceName($('source').value))} ×</button>`);if($('pcb').checked)chipHtml.push('<button type="button" data-remove-pcb="1" class="source-token">PCB用途 ×</button>');$('intentChips').innerHTML=chipHtml.join('');$('ingredientCount').textContent=components.length?`已选 ${components.length} 种`:'多选组分';const note=intentWarnings.length?intentWarnings.join(' ')+(hasRecognizedIntent({components,exclude_components:excludedIngredients,filters:intentFilters,q:$('query').value,source:$('source').value,pcb:$('pcb').checked})?' 已按其余可识别条件检索。':' 请在高级筛选中补全。'):'';$('interpretNote').textContent=note;$('interpretNote').hidden=!note;chips()}
async function runIntent(){if(ingredientBusy||!summary)return;ingredientBusy=true;$('engineSubmit').disabled=true;$('engineSubmit').textContent='正在查找…';$('intentError').hidden=true;$('intentError').classList.remove('soft');$('searchSuggestions').hidden=true;try{const d=await get('/api/glass/interpret?'+new URLSearchParams({text:$('intent').value}));parsedIngredients=d.components;components=[...new Set([...pickedIngredients,...d.components])];intentFilters=d.filters;excludedIngredients=d.exclude_components;intentWarnings=d.warnings;$('query').value=d.q;$('source').value=d.source;$('pcb').checked=d.pcb;system='';offset=0;for(const k of ['kind','lo','hi'])$(k).value='';if(intentFilters[0])fillAdvancedFromFilter(intentFilters[0]);else fillAdvancedFromFilter(null);renderIntent();lastIntentText=$('intent').value;const recognized=hasRecognizedIntent(d);if(d.warnings.length){document.body.classList.add('advanced-open');window.revealResults();$('intentError').hidden=false;$('intentError').classList.add('soft');$('intentError').textContent=(recognized?'部分条件尚未识别完整，已按其余条件检索。':'未能识别可检索的条件，请改用示例或在高级筛选中设置。')+' '+d.warnings.join(' ')}if(recognized){view='recipes';await search()}else if(!$('intent').value.trim()){view='systems';await search()}}catch(e){$('intentError').hidden=false;$('intentError').classList.remove('soft');$('intentError').textContent=e.message}finally{ingredientBusy=false;$('engineSubmit').disabled=false;$('engineSubmit').innerHTML='搜索材料 <span>→</span>'}}
$('engineForm').onsubmit=e=>{e.preventDefault();runIntent()};$('intent').onfocus=()=>{$('searchSuggestions').hidden=false};$('intent').onkeydown=e=>{if(e.key==='Escape')$('searchSuggestions').hidden=true};document.addEventListener('click',e=>{if(!e.target.closest('.engine-wrap'))$('searchSuggestions').hidden=true});$('searchSuggestions').onclick=e=>{const b=e.target.closest('[data-example]');if(b){$('intent').value=b.dataset.example;runIntent()}};
function openIngredients(){renderIngredients();$('ingredientModal').showModal();$('ingredientQuery').focus({preventScroll:true});$('ingredientModal').scrollTop=0}
$('openIngredients').onclick=$('openIngredientsAside').onclick=openIngredients;$('closeIngredients').onclick=()=>$('ingredientModal').close();$('ingredientQuery').oninput=renderIngredients;$('ingredientTabs').onclick=e=>{const b=e.target.closest('[data-ingredient-tab]');if(b){ingredientTab=b.dataset.ingredientTab;renderIngredients()}};
function toggleIngredient(e){const b=e.target.closest('[data-ingredient]');if(!b)return;const k=b.dataset.ingredient;if(components.includes(k)){components=components.filter(x=>x!==k);pickedIngredients.delete(k);parsedIngredients=parsedIngredients.filter(x=>x!==k)}else{components.push(k);pickedIngredients.add(k)}renderIngredients();renderIntent()}
$('ingredientGrid').onclick=$('ingredientSelected').onclick=toggleIngredient;$('clearIngredients').onclick=()=>{components=[];pickedIngredients.clear();parsedIngredients=[];renderIngredients();renderIntent()};$('applyIngredients').onclick=()=>{$('ingredientModal').close();if($('intent').value.trim()&&$('intent').value!==lastIntentText){runIntent();return}system='';offset=0;view='recipes';renderIntent();search()};
$('intentChips').onclick=e=>{const edit=e.target.closest('[data-edit-filter]');if(edit){const f=intentFilters[Number(edit.dataset.editFilter)];if(!f)return;fillAdvancedFromFilter(f);document.body.classList.add('advanced-open');window.revealResults();$('lo').focus({preventScroll:true});return}const b=e.target.closest('button');if(!b)return;if(b.dataset.removeFilter!=null){const i=Number(b.dataset.removeFilter);const removed=intentFilters[i];intentFilters.splice(i,1);if(removed&&$('kind').value){try{const[kind,unit]=JSON.parse($('kind').value);if(removed.kind===kind&&removed.unit===unit)fillAdvancedFromFilter(intentFilters.find(f=>f.kind===kind&&f.unit===unit)||null)}catch{}}}if(b.dataset.removeComponent){components=components.filter(k=>k!==b.dataset.removeComponent);pickedIngredients.delete(b.dataset.removeComponent)}if(b.dataset.removeExclude)excludedIngredients=excludedIngredients.filter(k=>k!==b.dataset.removeExclude);if(b.dataset.removeQuery)$('query').value='';if(b.dataset.removeSource)$('source').value='';if(b.dataset.removePcb)$('pcb').checked=false;offset=0;renderIntent();search()};
$('advancedToggle').onclick=()=>{document.body.classList.toggle('advanced-open');window.revealResults();if(document.body.classList.contains('advanced-open')&&intentFilters[0]&&!$('kind').value)fillAdvancedFromFilter(intentFilters[0])};$('browse').onclick=()=>$('reset').onclick();const oldReset=$('reset').onclick;$('reset').onclick=()=>{intentFilters=[];excludedIngredients=[];intentWarnings=[];pickedIngredients.clear();$('intent').value='';fillAdvancedFromFilter(null);$('intentError').hidden=true;$('intentError').classList.remove('soft');oldReset();renderIntent()};
const oldApply=$('apply').onclick;$('apply').onclick=()=>{upsertAdvancedIntoIntent();renderIntent();oldApply();if($('kind').value||intentFilters.length){view='recipes';offset=0;search()}};
function searchReady(){renderIngredients();renderIntent()}
if(summary)searchReady();else window.addEventListener('catalog-ready',searchReady,{once:true});
